// Origin item is the Stores row that triggered this branch (Get Stores for Geocoding),
// looked up by pairedItem rather than $json since $json here is the HTTP response body.
const store = $('Get Stores for Geocoding').item.json.store;
const resp = $json;
const element = resp?.rows?.[0]?.elements?.[0];

if (!element || element.status !== 'OK') {
  return [{ json: { store, ok: false, reason: element?.status || 'no_response' } }];
}

const miles = Math.round((element.distance.value / 1609.34) * 10) / 10;

// Round-trip cost estimate using a standard per-mile rate as a stand-in for real
// gas/wear-and-tear cost — a rough default, not a precise trip-cost model. Overwrite
// est_trip_cost by hand directly in the Stores sheet later if a better number is known;
// this only fills the cell, it never overwrites a value someone already entered manually
// (see the Missing Distance? filter upstream).
const MILEAGE_RATE_PER_MI = 0.67;
const estTripCost = Math.round(miles * 2 * MILEAGE_RATE_PER_MI * 100) / 100;

return [{ json: { store, ok: true, distance_from_home_mi: miles, est_trip_cost: estTripCost } }];

// Bulk-trip economics per architecture.md §7, with the confidence gate from the same section:
// 8 completed cycles before a recommendation is 'reliable' rather than 'provisional'.
const RELIABLE_CYCLE_THRESHOLD = 8;

// $input.all() holds three parallel branches merged combineAll: Catalog rows, then Stores
// rows, then Inventory rows, in that order (mirrors how the existing Webhook Agent reads
// its two merged branches via named-node lookups rather than trusting input order).
const catalogRows = $('Get Catalog').all().map(i => i.json);
const storeRows = $('Get Stores').all().map(i => i.json);
const inventoryRows = $('Get Inventory').all().map(i => i.json);

const storeByName = new Map(storeRows.map(s => [s.store, s]));
const inventoryByItem = new Map(inventoryRows.map(r => [r.item, r]));

const unitPriceOf = (row) => {
  const up = Number(row.unit_price);
  if (up > 0) return up;
  const p = Number(row.price);
  return p > 0 ? p : null; // falls back to raw price if no unit_price, same convention as the app's priceOf()
};

// Group Catalog rows by item
const byItem = new Map();
for (const row of catalogRows) {
  if (!byItem.has(row.item)) byItem.set(row.item, []);
  byItem.get(row.item).push(row);
}

const recommendations = [];

for (const [item, rows] of byItem.entries()) {
  if (rows.length < 2) continue; // needs at least two stores to compare
  const inv = inventoryByItem.get(item);
  const avgDaysToFinish = inv ? Number(inv.avg_days_to_finish) : null;
  if (!avgDaysToFinish || avgDaysToFinish <= 0) continue; // no consumption-rate data yet
  const cycleCount = inv ? (Number(inv.cycle_count) || 0) : 0;
  const annualQty = 365 / avgDaysToFinish;

  const withStoreInfo = rows
    .map(r => ({ ...r, _unitPrice: unitPriceOf(r), _store: storeByName.get(r.store) }))
    .filter(r => r._unitPrice != null && r._store && Number(r._store.distance_from_home_mi) >= 0);
  if (withStoreInfo.length < 2) continue;

  withStoreInfo.sort((a, b) => Number(a._store.distance_from_home_mi) - Number(b._store.distance_from_home_mi));
  const near = withStoreInfo[0];

  for (const bulk of withStoreInfo.slice(1)) {
    if (bulk._unitPrice >= near._unitPrice) continue; // not actually cheaper — no recommendation
    const annualSavings = (near._unitPrice - bulk._unitPrice) * annualQty;
    const tripCost = Number(bulk._store.est_trip_cost) || 0;
    // V1 simplification (see Setup Notes): single-item annual savings must clear one trip's
    // cost on its own — conservative, doesn't credit trip-bundling across multiple items.
    if (annualSavings <= tripCost) continue;

    recommendations.push({
      item,
      nearStore: near.store,
      bulkStore: bulk.store,
      annualSavings: Math.round(annualSavings * 100) / 100,
      tripCost,
      cycleCount,
      reliable: cycleCount >= RELIABLE_CYCLE_THRESHOLD,
    });
  }
}

return recommendations.map(r => ({ json: r }));

// Guarantees exactly one output item regardless of how many recommendations came out of
// the previous node (including zero) — an If/Switch node given zero input items fires on
// NEITHER branch in n8n, which would silently swallow the 'nothing to recommend' case if
// this check node weren't here. A Code node in 'Run Once for All Items' mode always runs.
const items = $input.all().map(i => i.json);
return [{ json: { hasRecommendations: items.length > 0, items } }];

// Same caution-icon convention already used in the app for missing pack sizes
// (household-ledger-architecture.md §7's 'Confidence gate' section), applied here to
// data maturity instead: below-threshold recommendations get a ⚠️ provisional caveat,
// at-threshold-or-above ones are stated plainly.
const RELIABLE_CYCLE_THRESHOLD = 8;
const lines = $json.items.map(r => {
  const caveat = r.reliable
    ? ''
    : ` (\u26A0\uFE0F provisional \u2014 based on ${r.cycleCount} of ${RELIABLE_CYCLE_THRESHOLD} purchase cycles)`;
  return `${r.item}: ${r.nearStore} \u2192 ${r.bulkStore} could save ~$${r.annualSavings.toFixed(2)}/yr `
    + `(trip cost $${r.tripCost.toFixed(2)})${caveat}`;
});
const text = `\uD83D\uDCE6 Bulk-trip recommendations this week:\n\n${lines.join('\n')}`;
return [{ json: { text } }];
